package com.learningspace;
import java.io.*;import java.nio.file.*;import org.json.*;
public class ShareDraftsCheck {
 public static void main(String[] args)throws Exception{if(!LocalImages.raster("data:image/png;base64,aGVsbG8=" )||!LocalImages.raster("data:image/jpeg;base64,aGVsbG8=")||LocalImages.raster("data:image/svg+xml;base64,aGVsbG8=")||LocalImages.raster("https://example.com/image.png")||LocalImages.raster("data:image/png;base64,<script>"))throw new Exception("Local image allowlist failed");File file=new File(Files.createTempDirectory("learning-shares-").toFile(),"pending.json");String text="A useful thread https://x.com/example/status/123";ShareDrafts.add(file,"share-one",text);ShareDrafts.add(file,"share-one",text);if(ShareDrafts.read(file).length()!=1)throw new Exception("Duplicate share");ShareDrafts.add(file,"share-two",new String(new char[20000]).replace('\0','a'));if(ShareDrafts.read(file).getJSONObject(1).getString("text").length()>10000)throw new Exception("Unbounded share");ShareDrafts.acknowledge(file,"share-one");if(ShareDrafts.read(file).length()!=1||!ShareDrafts.read(file).getJSONObject(0).getString("id").equals("share-two"))throw new Exception("Wrong acknowledgement");ShareDrafts.acknowledge(file,"share-two");if(ShareDrafts.read(file).length()!=0)throw new Exception("Queue not cleared");for(int i=0;i<20;i++)ShareDrafts.add(file,"share-"+i,text);boolean rejected=false;try{ShareDrafts.add(file,"too-many",text);}catch(IOException e){rejected=true;}if(!rejected||ShareDrafts.read(file).length()!=20)throw new Exception("Queue bound failed");file.delete();file.getParentFile().delete();System.out.println("Native incoming share checks passed: durable drafts, idempotency, text bounds, acknowledgement, capacity, and local raster image allowlist.");}
}
